-- LUEMI coarse city-distance reference for automatic "Рядом" recommendations.
-- Source: GeoNames cities15000 (cities over 15,000 residents and capitals).
-- © GeoNames contributors, CC BY 4.0 https://www.geonames.org/ (data as is).
-- https://download.geonames.org/export/dump/cities15000.zip
-- Extra known offline local centres are from LUEMI's previous geodata module.
-- Only PUBLIC city centroids, NEVER personal GPS coordinates; no account data is modified.
-- When a city is missing, API keeps other profiles and uses honest coarse fallback.
BEGIN;
CREATE TABLE IF NOT EXISTS luemi_private.city_centres (
 country_code char(2) NOT NULL CHECK(country_code ~ '^[A-Z]{2}$'),
 city_norm text NOT NULL CHECK(length(city_norm) BETWEEN 2 AND 120),
 lat double precision NOT NULL CHECK(lat BETWEEN -90 AND 90),
 lon double precision NOT NULL CHECK(lon BETWEEN -180 AND 180),
 population bigint NOT NULL DEFAULT 0 CHECK(population>=0),
 PRIMARY KEY(country_code,city_norm)
);
ALTER TABLE luemi_private.city_centres ENABLE ROW LEVEL SECURITY;
ALTER TABLE luemi_private.city_centres FORCE ROW LEVEL SECURITY;
REVOKE ALL ON luemi_private.city_centres FROM PUBLIC,anon,authenticated;
GRANT SELECT ON luemi_private.city_centres TO luemi_discovery_reader;
CREATE POLICY city_centres_reference_read ON luemi_private.city_centres
 FOR SELECT TO luemi_discovery_reader USING(true);
ON CONFLICT(country_code,city_norm) DO UPDATE SET lat=EXCLUDED.lat,lon=EXCLUDED.lon,population=EXCLUDED.population;
